double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const double* W1 = params;
    const double* b1 = params + n_hidden * n_in;
    const double* W2 = b1 + n_hidden;
    const double b2 = W2[n_hidden];

    double* grad_W1 = grad;
    double* grad_b1 = grad + n_hidden * n_in;
    double* grad_W2 = grad_b1 + n_hidden;
    double* grad_b2 = grad_W2 + n_hidden;

    for (int i = 0; i < n_hidden * n_in; ++i) grad_W1[i] = 0.0;
    for (int i = 0; i < n_hidden; ++i) grad_b1[i] = 0.0;
    for (int i = 0; i < n_hidden; ++i) grad_W2[i] = 0.0;
    *grad_b2 = 0.0;

    double total_loss = 0.0;

    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        double ys = y[s];

        double h[n_hidden];
        for (int j = 0; j < n_hidden; ++j) {
            double sum = b1[j];
            for (int k = 0; k < n_in; ++k) {
                sum += W1[j * n_in + k] * x[k];
            }
            h[j] = tanh(sum);
        }

        double z = b2;
        for (int j = 0; j < n_hidden; ++j) {
            z += W2[j] * h[j];
        }

        double p = 1.0 / (1.0 + exp(-z));
        double loss = -(ys * log(p + 1e-10) + (1 - ys) * log(1 - p + 1e-10));
        total_loss += loss;

        double dp_dz = p * (1 - p);
        double dz_db2 = 1.0;
        double dz_dW2j = h[j];
        double dz_dhj = W2[j];

        double dhj_dzj = 1.0 - h[j] * h[j];
        double dzj_dW1jk = x[k];
        double dzj_db1j = 1.0;

        double dL_dz = dp_dz * (p - ys);
        *grad_b2 += dL_dz * dz_db2;

        for (int j = 0; j < n_hidden; ++j) {
            double dL_dhj = dL_dz * dz_dhj;
            grad_W2[j] += dL_dhj * dz_dW2j;
            double dL_dzj = dL_dhj * dhj_dzj;
            grad_b1[j] += dL_dzj * dzj_db1j;
            for (int k = 0; k < n_in; ++k) {
                grad_W1[j * n_in + k] += dL_dzj * dzj_dW1jk;
            }
        }
    }

    double avg_loss = total_loss / n_samples;
    for (int i = 0; i < n_hidden * n_in; ++i) grad_W1[i] /= n_samples;
    for (int i = 0; i < n_hidden; ++i) grad_b1[i] /= n_samples;
    for (int i = 0; i < n_hidden; ++i) grad_W2[i] /= n_samples;
    *grad_b2 /= n_samples;

    return avg_loss;
}
